    <style>
        :root{--navy:#21133d;--purple:#59369b;--coral:#f4674a;--mint:#1d9b69;--sun:#ffc857;--paper:#fffdfa;--soft:#fff4ec;--ink:#241432;--muted:#71647d;--line:#ebdfeb}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:Cairo,Arial,sans-serif;line-height:1.8}a{text-decoration:none;color:inherit}.container{width:min(1140px,calc(100% - 36px));margin:auto}.hero{position:relative;overflow:hidden;background:var(--navy);color:#fff;padding:92px 0 120px}.hero:before{content:'طموح';position:absolute;left:-35px;bottom:-80px;color:#ffffff08;font-size:260px;font-weight:800;line-height:1}.hero:after{content:'';position:absolute;right:9%;top:-190px;width:430px;height:430px;border:1px solid #ffffff1c;border-radius:50%;box-shadow:0 0 0 35px #ffffff08,0 0 0 70px #ffffff04}.hero .container{position:relative;z-index:1}.hero-layout{display:grid;grid-template-columns:1.1fr .9fr;gap:70px;align-items:center}.hero-copy{max-width:620px}.eyebrow{display:inline-flex;align-items:center;gap:10px;color:var(--sun);font-size:12px;font-weight:800}.eyebrow:before{content:'';width:30px;height:2px;background:var(--sun)}.hero h1{font-size:clamp(37px,5vw,64px);line-height:1.35;margin:18px 0 14px}.hero h1 span{color:var(--sun)}.hero p{max-width:530px;color:#ded2e8;font-size:14px;margin:0}.hero-actions{display:flex;gap:12px;align-items:center;margin-top:28px}.button-main{display:inline-block;padding:12px 21px;border-radius:12px;background:var(--coral);color:#fff;font-size:13px;font-weight:800;transition:.2s}.button-main:hover{background:#df4e33;transform:translateY(-3px)}.button-line{padding:9px 3px;color:#fff;border-bottom:1px solid #ffffff66;font-size:12px;font-weight:700}.hero-visual{position:relative;min-height:350px}.visual-card{position:absolute;right:25px;top:12px;width:270px;height:290px;padding:22px;background:linear-gradient(145deg,#704bb2,#3c246c);border-radius:28px 28px 7px 28px;transform:rotate(5deg);box-shadow:22px 25px 0 #f4674a}.visual-card:before{content:'01';display:block;color:#ffffff55;font-size:70px;font-weight:800;line-height:1}.visual-card h2{font-size:25px;line-height:1.5;margin:48px 0 3px}.visual-card p{color:#dcd0ed;font-size:11px;margin:0}.visual-note{position:absolute;left:0;bottom:34px;width:165px;padding:15px;background:#fff;color:var(--ink);border-radius:15px;box-shadow:0 15px 35px #10071e55;transform:rotate(-6deg)}.visual-note strong{display:block;color:var(--coral);font-size:24px}.visual-note span{font-size:11px}.hero-stats{display:flex;gap:0;margin-top:42px}.hero-stat{padding-left:24px;margin-left:24px;border-left:1px solid #ffffff35}.hero-stat:last-child{border-left:0;margin-left:0}.hero-stat strong{display:block;color:var(--sun);font-size:22px}.hero-stat span{color:#cfc0dd;font-size:10px}.section{padding:92px 0}.section-heading{display:flex;align-items:end;justify-content:space-between;gap:30px;margin-bottom:34px}.section-heading h2{font-size:30px;line-height:1.45;margin:8px 0 0}.section-heading p{max-width:380px;color:var(--muted);font-size:13px;margin:0}.section-heading .eyebrow{color:var(--coral)}.section-heading .eyebrow:before{background:var(--coral)}.bento{display:grid;grid-template-columns:1.15fr .85fr .85fr;grid-template-rows:180px 180px;gap:15px}.bento-card{position:relative;overflow:hidden;padding:22px;background:#fff;border:1px solid var(--line);border-radius:22px}.bento-card:first-child{grid-row:span 2;background:var(--soft);border:0}.bento-card:nth-child(2){background:#e9f8f1}.bento-card:nth-child(3){background:#fff5d9}.bento-card:nth-child(4){grid-column:span 2;background:var(--purple);color:#fff}.bento-card h3{font-size:18px;margin:8px 0 2px}.bento-card p{color:var(--muted);font-size:11px;max-width:240px;margin:0}.bento-card:first-child p,.bento-card:nth-child(4) p{color:inherit;opacity:.8}.bento-icon{font-size:30px;font-weight:800;color:var(--coral)}.bento-card:nth-child(2) .bento-icon{color:var(--mint)}.bento-card:nth-child(3) .bento-icon{color:#d79d13}.bento-card:nth-child(4) .bento-icon{color:var(--sun)}.bento-number{position:absolute;left:20px;bottom:-21px;color:#ffffff44;font-size:105px;font-weight:800;line-height:1}.bento-card a{display:inline-block;position:relative;margin-top:15px;color:var(--coral);font-size:11px;font-weight:800}.journey{background:var(--soft)}.journey-layout{display:grid;grid-template-columns:.75fr 1.25fr;gap:75px;align-items:center}.journey-intro h2{font-size:33px;line-height:1.5;margin:8px 0 13px}.journey-intro p{color:var(--muted);font-size:13px}.journey-list{display:grid;gap:13px}.journey-step{display:grid;grid-template-columns:64px 1fr;gap:17px;align-items:center;padding:16px 18px;background:#fff;border:1px solid var(--line);border-radius:16px}.journey-step:nth-child(2){margin-right:34px}.journey-step:nth-child(3){margin-right:68px}.step-number{width:50px;height:50px;display:grid;place-items:center;border-radius:50%;background:var(--coral);color:#fff;font-size:16px;font-weight:800}.journey-step:nth-child(2) .step-number{background:var(--mint)}.journey-step:nth-child(3) .step-number{background:var(--purple)}.journey-step h3{font-size:15px;margin:0 0 2px}.journey-step p{color:var(--muted);font-size:11px;margin:0}.teachers{background:var(--navy);color:#fff}.teachers .section-heading p{color:#cfc0dd}.teachers .section-heading .eyebrow{color:var(--sun)}.teachers .section-heading .eyebrow:before{background:var(--sun)}.teacher-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.teacher-card{padding:20px;background:#32204f;border:1px solid #684c8b;border-radius:18px;transition:.2s}.teacher-card:hover{transform:translateY(-5px);background:#3b2560}.teacher-photo{width:72px;height:72px;display:grid;place-items:center;overflow:hidden;border-radius:50% 50% 10px 50%;background:var(--sun);color:var(--ink);font-size:24px;font-weight:800}.teacher-photo img{width:100%;height:100%;object-fit:cover}.teacher-card h3{font-size:16px;margin:14px 0 0}.teacher-card small{color:var(--sun);font-size:11px}.teacher-card p{color:#d7cce3;font-size:11px;line-height:1.8;margin:8px 0}.teacher-card .tag{display:inline-block;padding:3px 9px;background:#ffffff12;color:#eee7f4;font-size:10px;border-radius:5px}.teacher-loading{grid-column:1/-1;color:#d7cce3;font-size:13px}.cta{padding:82px 0}.cta-box{position:relative;overflow:hidden;display:flex;align-items:center;justify-content:space-between;gap:25px;padding:36px 42px;background:var(--mint);color:#fff;border-radius:24px}.cta-box:after{content:'؟';position:absolute;left:25px;bottom:-72px;color:#ffffff25;font-size:190px;font-weight:800;line-height:1}.cta-box h2{font-size:27px;margin:0}.cta-box p{font-size:13px;margin:4px 0 0}.cta-box .button-main{position:relative;z-index:1;background:var(--sun);color:var(--ink)}.footer{padding:25px 0;background:#fff;color:var(--muted);font-size:11px;border-top:1px solid var(--line)}.footer-inner{display:flex;justify-content:space-between;align-items:center}.footer-brand{display:flex;gap:9px;align-items:center;color:var(--ink);font-weight:800}.footer-brand img{width:34px;height:34px;border-radius:9px}.footer-brand small{display:block;color:var(--muted);font-weight:400}.reveal{animation:rise .7s both}@keyframes rise{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}@media(max-width:820px){.hero-layout,.journey-layout{grid-template-columns:1fr;gap:35px}.hero{padding-top:65px}.hero-visual{min-height:310px;max-width:430px;margin:auto;width:100%}.section{padding:68px 0}.bento{grid-template-columns:1fr 1fr;grid-template-rows:auto}.bento-card:first-child{grid-row:auto;grid-column:span 2}.bento-card:nth-child(4){grid-column:span 2}.teacher-grid{grid-template-columns:1fr}.journey-step:nth-child(2),.journey-step:nth-child(3){margin-right:0}}@media(max-width:520px){.hero h1{font-size:35px}.hero-stats{gap:8px}.hero-stat{padding-left:10px;margin-left:10px}.hero-stat strong{font-size:17px}.hero-stat span{font-size:9px}.hero-visual{transform:scale(.9);transform-origin:center}.section-heading{display:block}.section-heading p{margin-top:13px}.bento{display:flex;flex-direction:column}.bento-card{min-height:155px}.bento-card:first-child{min-height:205px}.cta-box{display:block;padding:28px 24px}.cta-box .button-main{display:inline-block;margin-top:19px}.footer-inner{display:block}.footer-inner>span{display:block;margin-top:12px}}
