<script>
document.addEventListener('DOMContentLoaded',function(){var teachersBox=document.querySelector('#home-teachers');var escapeHtml=function(value){var element=document.createElement('div');element.textContent=value||'';return element.innerHTML;};var initial=function(name){return Array.from(name||'م')[0]||'م';};fetch('{{ route('api.home-teachers') }}').then(function(response){return response.json();}).then(function(data){if(!data.ok||!data.teachers.length){teachersBox.innerHTML='<p class="teacher-loading">سيتم عرض المدرسين المعتمدين هنا قريبًا.</p>';return;}teachersBox.innerHTML=data.teachers.map(function(teacher){var name=escapeHtml(teacher.full_name);var photo=teacher.photo_path?'<img src="/'+escapeHtml(teacher.photo_path.replace('public/',''))+'" alt="'+name+'">':'<span>'+initial(teacher.full_name)+'</span>';return '<a class="teacher-card" href="{{ url('/teachers') }}/'+encodeURIComponent(teacher.id)+'"><div class="teacher-photo">'+photo+'</div><h3>'+name+'</h3><small>'+escapeHtml(teacher.specialization||'مدرس معتمد')+'</small><p>'+escapeHtml(teacher.bio||'مدرس متخصص لمتابعة الطلاب وتبسيط المادة التعليمية.')+'</p><span class="tag">'+escapeHtml(teacher.subjects||'المواد قريبًا')+'</span></a>';}).join('');}).catch(function(){teachersBox.innerHTML='<p class="teacher-loading">تعذر تحميل المدرسين حاليًا.</p>';});});
</script>
